/** The only way a sector is produced. Anything unrecognized reads OTHERS
 *  rather than throwing, so a render path can never crash on bad data. */
export function sectorOf(industryGroup) {
  if (!industryGroup) return OTHERS;
  return INDUSTRY_GROUP_TO_SECTOR[industryGroup] || OTHERS;
}

/** Mirrors pipeline/taxonomy/gics.py's classify(), including its evidence
 *  priority: manual override > raw industry label > legacy sector.
 *  Returns { industryGroup, sector, source } -- never null. */
export function classifyGics({ symbol, industry, sector, universe } = {}) {
  if (symbol && universe) {
    const ig = (MANUAL_OVERRIDE[universe] || {})[String(symbol).trim().toUpperCase()];
    if (ig) return { industryGroup: ig, sector: sectorOf(ig), source: "manual_override" };
  }
  // A label resolving to OTHERS is remembered, not returned: a real legacy
  // sector still beats a vendor's "Miscellaneous". It only decides whether the
  // fallthrough reports evidence-backed OTHERS or no evidence at all.
  let sawExplicitOthers = false;
  if (industry) {
    const ig = RAW_TO_INDUSTRY_GROUP[String(industry).trim()];
    if (ig && ig !== OTHERS) return { industryGroup: ig, sector: sectorOf(ig), source: "raw_industry" };
    sawExplicitOthers = sawExplicitOthers || ig === OTHERS;
  }
  if (sector) {
    const ig = LEGACY_SECTOR_TO_INDUSTRY_GROUP[String(sector).trim()];
    if (ig && ig !== OTHERS) return { industryGroup: ig, sector: sectorOf(ig), source: "legacy_sector" };
    sawExplicitOthers = sawExplicitOthers || ig === OTHERS;
  }
  return {
    industryGroup: OTHERS, sector: OTHERS,
    source: sawExplicitOthers ? "explicit_others" : "unclassified",
  };
}
